insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-09-08','opgelost','Dashboard','Tellers op het startscherm laten weer het echte aantal zien',
   'De widgets op je startscherm telden alleen de regels die in het kaartje pasten. Stonden er meer opdrachten, aanvragen, servicedeskdossiers, acties of agenda-items open, dan zag je een te laag getal. De kop toont nu het volledige aantal; de lijst eronder blijft de eerste paar regels tonen.');
